    "fullDescription": "Джамал Малик, 18-летний сирота из трущоб в Мумбаи, всего в одном шаге от победы в телеигре «Кто хочет стать миллионером?» и выигрыша 20 миллионов рупий. Прервав игру, его арестовывает полиция по подозрению в мошенничестве. Откуда юнец, выросший на улице, может знать так много?\nНа допросе в полиции Джамал рассказывает печальную историю своей жизни: о пережитых приключениях вместе с братом, о стычках с местными бандами, о своей трагической любви. Каждая глава личной истории удивительным образом дала ему ответы на вопросы телевикторины.\nКогда игру возобновят, инспектору полиции и шестидесяти миллионам зрителей захочется выяснить ответ только на один вопрос: зачем этот юноша, без явного стремления к богатству, решил принять участие в телепрограмме?",
